import { redirect } from 'next/navigation'
import { LINKS } from '@/lib/links'

export const metadata = {
  title: 'Apply — Inner Circle | Kennedy Muritu',
}

/** The application lives on Tally (same form as the Inner Circle site). */
export default function CommunityApplyPage() {
  redirect(LINKS.icJoinForm)
}

import Link from 'next/link'
import { notFound } from 'next/navigation'
import { getEssayBySlug } from '@/lib/queries'

export default async function EssayPage({ params }: { params: Promise<{ slug: string }> }) {
  const { slug } = await params
  const essay = await getEssayBySlug(slug)
  if (!essay) notFound()

  const tags = essay.tags ? (JSON.parse(essay.tags) as string[]) : []

  return (
    <div className="min-h-screen bg-background text-foreground">
      <header className="border-b border-border px-6 py-4 max-w-3xl mx-auto">
        <Link href="/essays" className="font-mono text-primary text-sm">← All essays</Link>
      </header>
      <article className="max-w-3xl mx-auto px-6 py-16 font-serif text-lg leading-loose prose prose-neutral dark:prose-invert max-w-none">
        <h1 className="text-4xl font-display font-bold mb-4 not-prose">{essay.title}</h1>
        <div className="flex gap-3 text-sm font-mono text-muted-foreground mb-8 not-prose">
          {essay.publishedAt && <span>{essay.publishedAt.toLocaleDateString()}</span>}
          {tags.map((t) => (
            <span key={t} className="tag-pill text-[10px]">{t}</span>
          ))}
        </div>
        <div dangerouslySetInnerHTML={{ __html: essay.body }} />
        <footer className="mt-16 pt-8 border-t border-border not-prose">
          <p className="font-semibold">Kennedy Muritu</p>
          <p className="text-sm text-muted-foreground">Systems architect · Creative technologist · Kenya</p>
        </footer>
      </article>
    </div>
  )
}

'use client'

import { useState, useCallback, useEffect } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { X, ChevronLeft, ChevronRight, MapPin, LayoutGrid, Layers } from 'lucide-react'
import Stack from '@/components/ui/stack'
import { galleryCategories, type GalleryCategory, type GalleryPhotoDTO } from '@/lib/queries'
import { SectionHeading } from '@/components/section-heading'

function GalleryCard({ photo }: { photo: GalleryPhotoDTO }) {
  return (
    <div
      className="relative w-full h-full rounded-2xl overflow-hidden select-none"
      style={{
        boxShadow: '0 24px 60px rgba(0, 0, 0, 0.35), 0 0 0 1px rgba(20, 19, 15, 0.08)',
      }}
    >
      <img
        src={photo.src}
        alt={photo.caption}
        className="w-full h-full object-cover pointer-events-none"
        draggable={false}
        loading="lazy"
      />
      <div className="absolute inset-0 bg-gradient-to-t from-black/50 via-transparent to-transparent pointer-events-none" />
      <span className="absolute top-3 right-3 tag-pill text-[10px] backdrop-blur-sm bg-background/40">
        {photo.category}
      </span>
    </div>
  )
}

export default function GallerySection({ photos }: { photos: GalleryPhotoDTO[] }) {
  const [activeCategory, setActiveCategory] = useState<GalleryCategory>('All')
  const [activeIdx, setActiveIdx] = useState(0)
  const [showGrid, setShowGrid] = useState(false)
  const [lightbox, setLightbox] = useState<{ photo: GalleryPhotoDTO; index: number } | null>(null)

  const filtered = activeCategory === 'All'
    ? photos
    : photos.filter((p) => p.category === activeCategory)

  const navigate = useCallback(
    (dir: 1 | -1) => {
      if (!lightbox) return
      const newIdx = lightbox.index + dir
      if (newIdx >= 0 && newIdx < filtered.length) {
        setLightbox({ photo: filtered[newIdx], index: newIdx })
      }
    },
    [lightbox, filtered],
  )

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (!lightbox) return
      if (e.key === 'Escape') setLightbox(null)
      if (e.key === 'ArrowLeft') navigate(-1)
      if (e.key === 'ArrowRight') navigate(1)
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [lightbox, navigate])

  useEffect(() => {
    if (!lightbox) return
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = '' }
  }, [lightbox])

  if (photos.length === 0) return null

  const activePhoto = filtered[activeIdx] ?? filtered[0]

  const handleCategoryChange = (cat: GalleryCategory) => {
    setActiveCategory(cat)
    setActiveIdx(0)
    setShowGrid(false)
  }

  const openLightbox = (photo: GalleryPhotoDTO, index: number) => setLightbox({ photo, index })
  const closeLightbox = () => setLightbox(null)

  return (
    <section id="gallery" className="landing-section py-16 md:py-24">
      <div className="landing-container">
        <SectionHeading
          number="06"
          label="gallery"
          title="Life Gallery"
          subtitle="Events, moments & the life between the builds."
        />

        {/* Category filter */}
        <div className="flex flex-wrap gap-2 mb-12">
          {galleryCategories.map(cat => (
            <button
              key={cat}
              onClick={() => handleCategoryChange(cat)}
              className={`tag-pill transition-all duration-200 ${
                activeCategory === cat
                  ? 'border-primary text-primary bg-primary/10'
                  : 'hover:border-primary/50 hover:text-primary'
              }`}
            >
              {cat}
            </button>
          ))}
        </div>

        {/* ── Stack showcase ─────────────────────────────────── */}
        <div className="flex flex-col lg:flex-row lg:items-center lg:gap-16">

          {/* Stack card */}
          <div className="flex-shrink-0 flex flex-col items-center">
            <div className="w-[280px] h-[210px] sm:w-[360px] sm:h-[270px] md:w-[420px] md:h-[315px]">
              <Stack
                key={activeCategory}
                cards={filtered.map(photo => <GalleryCard key={photo.id} photo={photo} />)}
                randomRotation
                maxRotation={5}
                sensitivity={60}
                sendToBackOnClick
                autoplay
                autoplayDelay={3500}
                pauseOnHover
                onActiveChange={setActiveIdx}
              />
            </div>

            {/* Progress dots */}
            <div className="flex items-center gap-1.5 mt-8">
              {filtered.map((_, i) => (
                <motion.div
                  key={i}
                  animate={{ width: i === activeIdx ? 20 : 6 }}
                  transition={{ duration: 0.25 }}
                  className={`h-1.5 rounded-full ${i === activeIdx ? 'bg-primary' : 'bg-border'}`}
                />
              ))}
            </div>

            {/* Counter */}
            <p className="font-mono text-[11px] text-muted-foreground/40 mt-3 tracking-wide">
              {String(activeIdx + 1).padStart(2, '0')} / {String(filtered.length).padStart(2, '0')}
              &nbsp;·&nbsp;drag or click to advance
            </p>
          </div>

          {/* Caption panel */}
          <div className="mt-10 lg:mt-0 flex-1">
            <AnimatePresence mode="wait">
              <motion.div
                key={activePhoto?.id}
                initial={{ opacity: 0, x: 16 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: -16 }}
                transition={{ duration: 0.28, ease: [0.25, 0.1, 0.25, 1] }}
              >
                <span className="tag-pill mb-4 inline-block">{activePhoto?.category}</span>
                <p className="text-foreground font-display text-lg font-semibold leading-snug mb-3">
                  {activePhoto?.caption}
                </p>
                {activePhoto?.location && (
                  <p className="flex items-center gap-1.5 font-mono text-xs text-muted-foreground">
                    <MapPin size={11} className="text-primary/60" />
                    {activePhoto.location}
                    {activePhoto.date && <span className="opacity-50 ml-2">{activePhoto.date}</span>}
                  </p>
                )}
              </motion.div>
            </AnimatePresence>

            {/* Toggle between views */}
            <div className="flex items-center gap-3 mt-8">
              <button
                onClick={() => setShowGrid(v => !v)}
                className="inline-flex items-center gap-2 font-mono text-xs text-muted-foreground hover:text-primary border border-border hover:border-primary/40 px-4 py-2 rounded transition-all duration-200"
              >
                {showGrid ? (
                  <><Layers size={13} /> Stack view</>
                ) : (
                  <><LayoutGrid size={13} /> Browse all {filtered.length}</>
                )}
              </button>
            </div>
          </div>
        </div>

        {/* ── Expandable masonry grid ─────────────────────────── */}
        <AnimatePresence>
          {showGrid && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.4, ease: [0.25, 0.1, 0.25, 1] }}
              className="overflow-hidden"
            >
              <div className="columns-2 sm:columns-3 gap-3 mt-12">
                {filtered.map((photo, i) => (
                  <div
                    key={photo.id}
                    className="break-inside-avoid mb-3 cursor-pointer group"
                    onClick={() => openLightbox(photo, i)}
                  >
                    <div className="relative rounded-xl overflow-hidden border border-border hover:border-primary/40 transition-all duration-300">
                      <img
                        src={photo.src}
                        alt={photo.caption}
                        className="w-full h-auto object-cover transition-transform duration-500 group-hover:scale-105"
                        loading="lazy"
                      />
                      <div className="absolute inset-0 bg-black/0 group-hover:bg-black/30 transition-all duration-300 pointer-events-none" />
                    </div>
                  </div>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* ── Lightbox ───────────────────────────────────────────── */}
      <AnimatePresence>
        {lightbox && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            className="fixed inset-0 z-[60] bg-black/92 flex items-center justify-center p-4"
            onClick={closeLightbox}
          >
            <motion.div
              initial={{ scale: 0.9, opacity: 0 }}
              animate={{ scale: 1, opacity: 1 }}
              exit={{ scale: 0.92, opacity: 0 }}
              transition={{ duration: 0.2 }}
              className="relative max-w-4xl w-full"
              onClick={e => e.stopPropagation()}
            >
              <button
                onClick={closeLightbox}
                className="absolute -top-12 right-0 text-white/60 hover:text-white transition-colors"
                aria-label="Close lightbox"
              >
                <X size={24} />
              </button>

              <img
                src={lightbox.photo.src}
                alt={lightbox.photo.caption}
                className="w-full rounded-xl max-h-[75vh] object-contain"
              />

              <div className="mt-4 text-center">
                <p className="text-white font-medium">{lightbox.photo.caption}</p>
                <div className="flex items-center justify-center gap-4 text-white/50 text-xs font-mono mt-1">
                  {lightbox.photo.location && (
                    <span className="flex items-center gap-1">
                      <MapPin size={11} />
                      {lightbox.photo.location}
                    </span>
                  )}
                  {lightbox.photo.date && <span>{lightbox.photo.date}</span>}
                  <span className="text-primary/70">{lightbox.photo.category}</span>
                </div>
              </div>

              {lightbox.index > 0 && (
                <button
                  onClick={() => navigate(-1)}
                  className="absolute left-3 top-1/2 -translate-y-1/2 text-white/60 hover:text-white transition-colors bg-black/50 rounded-full p-2"
                  aria-label="Previous"
                >
                  <ChevronLeft size={24} />
                </button>
              )}
              {lightbox.index < filtered.length - 1 && (
                <button
                  onClick={() => navigate(1)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-white/60 hover:text-white transition-colors bg-black/50 rounded-full p-2"
                  aria-label="Next"
                >
                  <ChevronRight size={24} />
                </button>
              )}

              <p className="text-center text-white/30 text-xs font-mono mt-3">
                {lightbox.index + 1} / {filtered.length} · ← → to navigate · Esc to close
              </p>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>
    </section>
  )
}

