275	  .glass-elevated {
276	    backdrop-filter: blur(24px) saturate(200%);
277	    -webkit-backdrop-filter: blur(24px) saturate(200%);
278	    background: var(--glass-bg);
279	    border: 1px solid var(--glass-border);
280	    box-shadow:
281	      0 20px 60px var(--glass-shadow),
282	      inset 0 2px 0 rgba(255, 255, 255, 0.20),
283	      inset 0 -1px 0 rgba(0, 0, 0, 0.12);
284	    border-radius: var(--radius-2xl);
285	  }
