315	
316	  .glass-shimmer {
317	    position: relative;
318	    overflow: hidden;
319	  }
320	  .glass-shimmer::before {
321	    content: '';
322	    position: absolute;
323	    top: -50%;
324	    left: -60%;
325	    width: 40%;
326	    height: 200%;
327	    background: linear-gradient(
328	      105deg,
329	      transparent 0%,
330	      rgba(255, 255, 255, 0.06) 40%,
331	      rgba(255, 255, 255, 0.14) 50%,
332	      rgba(255, 255, 255, 0.06) 60%,
333	      transparent 100%
334	    );
335	    transform: skewX(-20deg);
336	    transition: left 0.6s ease;
337	    pointer-events: none;
338	  }
339	  .glass-shimmer:hover::before {
340	    left: 120%;
341	  }
342	
343	  .scroll-progress-bar {
