528	
529	  .admin-card {
530	    backdrop-filter: blur(12px) saturate(150%);
531	    -webkit-backdrop-filter: blur(12px) saturate(150%);
532	    background: var(--glass-bg);
533	    border: 1px solid var(--glass-border);
