@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&family=Newsreader:ital,opsz,wght@0,6..72,300;0,6..72,400;0,6..72,500;0,6..72,600;1,6..72,400&display=swap');

@tailwind base;
@tailwind components;
@tailwind utilities;

@layer components {
  .landing-container {
    @apply max-w-[1440px] mx-auto px-6 md:px-10 lg:px-12 w-full;
  }
  .landing-section {
    @apply py-16 md:py-24;
  }
  .landing-section-alt {
    @apply border-y;
    background-color: color-mix(in srgb, var(--surface-2) 30%, transparent);
    border-color: color-mix(in srgb, var(--border) 40%, transparent);
  }
  .hero-portrait-frame {
    @apply relative;
  }
  .text-landing-muted {
    color: var(--text-muted);
  }
  .pill {
    @apply inline-flex items-center rounded-full px-3 py-1 font-medium;
  }
  .pill-ink {
    @apply bg-primary text-primary-foreground;
  }
  .pill-outline {
    @apply border border-border text-muted-foreground bg-transparent;
  }
}

@layer utilities {
  @keyframes marquee {
    0% {
      transform: translateX(0);
    }
    100% {
      transform: translateX(-50%);
    }
  }
  .animate-marquee {
    animation: marquee 28s linear infinite;
  }
  .page-stack {
    @apply flex flex-col gap-4 w-full;
  }
}

:root {
  /* Core — paper & ink light theme (Inner Circle standard) */
  --background: #f4f1ea;
  --foreground: #14130f;
  --card: #faf8f2;
  --card-foreground: #14130f;
  --popover: #faf8f2;
  --popover-foreground: #14130f;
  --primary: #8a6f4e;
  --primary-foreground: #f8f5ef;
  --secondary: #eae6dc;
  --secondary-foreground: #443f35;
  --muted: #dcd7cb;
  --muted-foreground: #6f6a5e;
  --accent: #8a6f4e;
  --accent-foreground: #f8f5ef;
  --destructive: #a3402f;
  --destructive-foreground: #f8f5ef;
  --border: #dcd7cb;
  --input: #e6e1d6;
  --ring: #8a6f4e59;

  /* Surfaces */
  --surface-1: #faf8f2;
  --surface-2: #eeeae0;
  --surface-3: #e4dfd2;

  /* Text scale */
  --text-primary: #14130f;
  --text-secondary: #443f35;
  --text-muted: #6f6a5e;
  --text-accent: #8a6f4e;

  /* Extended accent */
  --accent-warm: #8a6f4e;
  --accent-warm-muted: #efe9dd;
  --accent-cool: #5c6670;

  /* Status */
  --success: #4a7a5c;
  --warning: #a08339;
  --error: #a3402f;
  --info: #5c6670;

  /* Glass */
  --glass-bg: rgba(250, 248, 242, 0.72);
  --glass-border: rgba(20, 19, 15, 0.08);
  --glass-shadow: rgba(20, 19, 15, 0.10);

  /* Radius */
  --radius-sm: 0.25rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;
  --radius: 0.75rem;

  /* Typography */
  --font-sans: 'Inter', 'SF Pro Display', system-ui, sans-serif;
  --font-display: 'Newsreader', 'Georgia', serif;
  --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
  --font-serif: 'Newsreader', 'Georgia', serif;

  --text-xs: 0.75rem;
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.25rem;
  --text-2xl: 1.5rem;
  --text-3xl: 1.875rem;
  --text-4xl: 2.25rem;
  --text-5xl: 3rem;
  --text-6xl: 3.75rem;

  /* Spacing */
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;
  --space-24: 6rem;
  --space-32: 8rem;

  /* Layout */
  --container-max: 1200px;
  --container-wide: 1400px;
  --container-narrow: 720px;

  /* Shadows — light */
  --shadow-sm: 0 1px 3px rgba(20, 19, 15, 0.06), 0 1px 2px rgba(20, 19, 15, 0.04);
  --shadow-md: 0 4px 12px rgba(20, 19, 15, 0.08), 0 2px 4px rgba(20, 19, 15, 0.06);
  --shadow-lg: 0 10px 30px rgba(20, 19, 15, 0.10), 0 4px 8px rgba(20, 19, 15, 0.06);
  --shadow-xl: 0 20px 60px rgba(20, 19, 15, 0.12), 0 8px 16px rgba(20, 19, 15, 0.08);
  --shadow-glow-primary: 0 0 20px rgba(138, 111, 78, 0.25);

  /* Gradients */
  --gradient-bg-light:
    radial-gradient(ellipse at 70% 10%, rgba(138, 111, 78, 0.04) 0%, transparent 55%),
    radial-gradient(ellipse at 30% 90%, rgba(111, 106, 94, 0.04) 0%, transparent 55%),
    #f4f1ea;

  /* Legacy aliases */
  --navy: #14130f;
  --light-navy: #1d1b16;
  --lightest-navy: #26241d;
  --slate: #6f6a5e;
  --light-slate: #a39d8d;
  --lightest-slate: #ece9e0;
  --white: #f4f1ea;
  --green: #8a6f4e;
  --green-tint: rgba(138, 111, 78, 0.1);
}

.dark {
  --background: #12110d;
  --foreground: #ece9e0;
  --card: #1a1915;
  --card-foreground: #ece9e0;
  --popover: #1a1915;
  --popover-foreground: #ece9e0;
  --primary: #a8895f;
  --primary-foreground: #14130f;
  --secondary: #26241d;
  --secondary-foreground: #ece9e0;
  --muted: #2c2a22;
  --muted-foreground: #a39d8d;
  --accent: #a8895f;
  --accent-foreground: #14130f;
  --destructive: #c96a56;
  --destructive-foreground: #14130f;
  --border: #2c2a22;
  --input: #2c2a22;
  --ring: #a8895f59;

  --surface-1: #1a1915;
  --surface-2: #201e18;
  --surface-3: #262420;

  --text-primary: #f4f1ea;
  --text-secondary: #c9c4b4;
  --text-muted: #a39d8d;
  --text-accent: #a8895f;

  --accent-warm: #a8895f;
  --accent-warm-muted: #a8895f18;
  --accent-cool: #8a939e;

  --success: #6f9c80;
  --warning: #b99a4e;
  --error: #c96a56;
  --info: #8a939e;

  --glass-bg: rgba(26, 25, 21, 0.70);
  --glass-border: rgba(236, 233, 224, 0.10);
  --glass-shadow: rgba(0, 0, 0, 0.40);

  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.30);
  --shadow-md: 0 4px 12px rgba(0, 0, 0, 0.40);
  --shadow-lg: 0 10px 30px rgba(0, 0, 0, 0.50);
  --shadow-xl: 0 20px 60px rgba(0, 0, 0, 0.60);
  --shadow-glow-primary: 0 0 20px rgba(168, 137, 95, 0.20);

  --gradient-bg-dark:
    radial-gradient(ellipse at 80% 0%, rgba(168, 137, 95, 0.04) 0%, transparent 60%),
    radial-gradient(ellipse at 20% 100%, rgba(138, 147, 158, 0.03) 0%, transparent 60%),
    #12110d;

  --green: #a8895f;
  --green-tint: rgba(168, 137, 95, 0.1);
}

@layer base {
  * {
    @apply border-border;
  }
  html {
    scroll-behavior: smooth;
  }
  body {
    @apply bg-background text-foreground font-sans antialiased;
    overflow-x: hidden;
    background: var(--gradient-bg-light);
  }
  .dark body {
    background: var(--gradient-bg-dark);
  }
  :focus-visible {
    outline: 2px solid var(--primary);
    outline-offset: 3px;
    border-radius: var(--radius-sm);
  }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after {
      animation-duration: 0.01ms !important;
      transition-duration: 0.01ms !important;
    }
    html {
      scroll-behavior: auto;
    }
  }
}

@layer components {
  /* ─── Liquid glass system ─── */
  .glass {
    backdrop-filter: blur(16px) saturate(180%);
    -webkit-backdrop-filter: blur(16px) saturate(180%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 8px 32px var(--glass-shadow),
      inset 0 1px 0 rgba(255, 255, 255, 0.15),
      inset 0 -1px 0 rgba(0, 0, 0, 0.08);
    border-radius: var(--radius-xl);
  }

  .glass-elevated {
    backdrop-filter: blur(24px) saturate(200%);
    -webkit-backdrop-filter: blur(24px) saturate(200%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 20px 60px var(--glass-shadow),
      inset 0 2px 0 rgba(255, 255, 255, 0.20),
      inset 0 -1px 0 rgba(0, 0, 0, 0.12);
    border-radius: var(--radius-2xl);
  }

  .glass-nav {
    backdrop-filter: blur(20px) saturate(160%);
    -webkit-backdrop-filter: blur(20px) saturate(160%);
    background: var(--glass-bg);
    border-bottom: 1px solid var(--glass-border);
    box-shadow: 0 1px 0 var(--glass-border), 0 4px 20px var(--glass-shadow);
  }

  .glass-card {
    backdrop-filter: blur(12px) saturate(150%);
    -webkit-backdrop-filter: blur(12px) saturate(150%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 4px 24px var(--glass-shadow),
      inset 0 1px 0 rgba(255, 255, 255, 0.12);
    border-radius: var(--radius-lg);
    transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }

  .glass-card:hover {
    border-color: var(--primary);
    box-shadow:
      0 8px 40px var(--glass-shadow),
      0 0 0 1px var(--primary),
      inset 0 1px 0 rgba(255, 255, 255, 0.20);
    transform: translateY(-2px);
  }

  .glass-shimmer {
    position: relative;
    overflow: hidden;
  }
  .glass-shimmer::before {
    content: '';
    position: absolute;
    top: -50%;
    left: -60%;
    width: 40%;
    height: 200%;
    background: linear-gradient(
      105deg,
      transparent 0%,
      rgba(255, 255, 255, 0.06) 40%,
      rgba(255, 255, 255, 0.14) 50%,
      rgba(255, 255, 255, 0.06) 60%,
      transparent 100%
    );
    transform: skewX(-20deg);
    transition: left 0.6s ease;
    pointer-events: none;
  }
  .glass-shimmer:hover::before {
    left: 120%;
  }

  .scroll-progress-bar {
    background: var(--primary);
    height: 2px;
  }

  .hero-mesh {
    background:
      radial-gradient(at 27% 37%, hsla(34, 32%, 55%, 0.07) 0px, transparent 50%),
      radial-gradient(at 97% 21%, hsla(38, 45%, 82%, 0.06) 0px, transparent 50%),
      radial-gradient(at 52% 99%, hsla(35, 28%, 45%, 0.05) 0px, transparent 50%),
      radial-gradient(at 10% 29%, hsla(40, 30%, 70%, 0.05) 0px, transparent 50%);
  }

  .gradient-text-light {
    background: linear-gradient(135deg, #14130f 0%, #8a6f4e 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .gradient-text-dark {
    background: linear-gradient(135deg, #f4f1ea 0%, #ece9e0 50%, #a8895f 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }

  .gradient-mint {
    background: linear-gradient(135deg, #a8895f 0%, #8a6f4e 50%, #6f5a3e 100%);
  }

  .gradient-forest {
    background: linear-gradient(135deg, #8a6f4e 0%, #a8895f 100%);
  }

  .section-gradient-dark {
    background: var(--gradient-bg-dark);
  }

  .section-gradient-light {
    background: var(--gradient-bg-light);
  }

  .section-label {
    @apply text-xs font-semibold tracking-[0.2em] uppercase text-primary mb-4;
  }

  .stack-tag {
    @apply inline-flex items-center px-3 py-1 rounded-full text-xs font-mono font-medium border transition-colors duration-200;
    background: var(--surface-2);
    color: var(--text-secondary);
    border-color: var(--border);
  }
  .stack-tag:hover {
    border-color: var(--primary);
  }

  .nav-link {
    @apply relative transition-colors duration-300 text-muted-foreground px-3 py-1.5 rounded-full;
  }
  .nav-link:hover {
    color: var(--primary);
  }
  .nav-link.active {
    color: var(--primary);
  }

  .btn-primary {
    @apply relative inline-flex items-center gap-2 px-6 py-3 font-semibold text-sm rounded-lg transition-all duration-200;
    @apply focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background;
    background: var(--primary);
    color: var(--primary-foreground);
    box-shadow: var(--shadow-md);
  }
  .btn-primary:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-2px);
    filter: brightness(1.05);
  }

  .btn-ghost {
    @apply inline-flex items-center gap-2 px-6 py-3 rounded-lg font-semibold text-sm transition-all duration-200;
    border: 1px solid var(--primary);
    color: var(--primary);
  }
  .btn-ghost:hover {
    background: var(--green-tint);
  }

  .social-icon {
    @apply transition-all duration-300 p-2;
    color: var(--text-muted);
  }
  .social-icon:hover {
    color: var(--primary);
    transform: translateY(-3px);
  }

  .scroll-indicator {
    animation: scrollBounce 2s infinite;
  }
  @keyframes scrollBounce {
    0%, 20%, 50%, 80%, 100% { transform: translateY(0) translateX(-50%); }
    40% { transform: translateY(10px) translateX(-50%); }
    60% { transform: translateY(5px) translateX(-50%); }
  }

  .section-header {
    @apply flex items-center gap-4 mb-12;
  }
  .section-title {
    @apply text-2xl sm:text-3xl md:text-4xl font-display font-semibold tracking-tight text-foreground whitespace-nowrap;
  }
  .section-line {
    @apply h-px bg-border flex-1 max-w-xs;
  }

  .tag-pill {
    @apply inline-flex items-center px-3 py-1 rounded-full text-xs font-mono border;
    color: var(--primary);
    border-color: var(--border);
    background: var(--surface-2);
  }

  .status-dot {
    @apply inline-block w-2 h-2 rounded-full;
  }
  .status-active {
    @apply bg-sage;
    box-shadow: 0 0 6px rgba(74, 122, 92, 0.5);
  }
  .status-progress {
    @apply bg-ochre;
  }
  .status-deployed {
    @apply bg-steel;
  }
  .status-concept {
    @apply bg-stone;
  }

  .admin-input {
    @apply w-full px-3 py-2.5 rounded-lg border border-border text-foreground text-sm transition-colors duration-200;
    background: var(--surface-2);
  }
  .admin-input:focus {
    outline: none;
    border-color: var(--primary);
    box-shadow: 0 0 0 2px var(--ring);
  }

  .page-enter {
    animation: fadeIn 0.6s ease-out both;
  }

  .interactive-min {
    min-width: 44px;
    min-height: 44px;
  }

  /* ─── Admin panel — liquid glass (design guide v3) ─── */
  .admin-shell {
    background: var(--gradient-bg-light);
    position: relative;
    isolation: isolate;
  }
  .dark .admin-shell {
    background: var(--gradient-bg-dark);
  }

  .admin-mesh {
    @apply absolute inset-0 pointer-events-none overflow-hidden;
    z-index: 0;
  }

  .admin-content-shell {
    @apply flex-1 flex flex-col min-w-0 w-full;
  }
  @media (min-width: 1024px) {
    .admin-content-shell {
      @apply my-3 mr-3 rounded-2xl border shadow-lg overflow-hidden;
      border-color: color-mix(in srgb, var(--border) 50%, transparent);
      background-color: color-mix(in srgb, var(--card) 20%, transparent);
    }
  }

  .admin-card {
    backdrop-filter: blur(12px) saturate(150%);
    -webkit-backdrop-filter: blur(12px) saturate(150%);
    background: var(--glass-bg);
    border: 1px solid var(--glass-border);
    box-shadow:
      0 4px 24px var(--glass-shadow),
      inset 0 1px 0 rgba(255, 255, 255, 0.12);
    border-radius: var(--radius-lg);
    transition: border-color 0.3s cubic-bezier(0.4, 0, 0.2, 1),
      box-shadow 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  }
  .admin-card-interactive {
    @apply admin-card glass-shimmer;
  }
  .admin-card-interactive:hover {
    border-color: var(--primary);
    box-shadow:
      0 8px 40px var(--glass-shadow),
      0 0 0 1px var(--primary),
      inset 0 1px 0 rgba(255, 255, 255, 0.20);
    transform: translateY(-2px);
  }

  .admin-stat-card {
    @apply admin-card-interactive p-4 md:p-5;
  }

  .admin-table-wrap {
    @apply admin-card overflow-hidden p-0;
  }
  .admin-table-wrap:hover {
    transform: none;
  }
  .admin-table-wrap table {
    @apply w-full text-sm;
  }

  .admin-sidebar {
    @apply glass;
    border-radius: 0;
    border-top: none;
    border-bottom: none;
    border-left: none;
    border-right: 1px solid var(--glass-border);
    box-shadow: 4px 0 24px var(--glass-shadow);
    z-index: 10;
  }

  .admin-header-bar {
    @apply glass-nav;
    z-index: 10;
  }

  .admin-nav-link {
    @apply relative flex items-center gap-2 px-3 py-2 rounded-lg text-sm font-mono transition-colors duration-200;
    color: var(--text-muted);
  }
  .admin-nav-link:hover {
    color: var(--primary);
    background: var(--green-tint);
  }
  .admin-nav-link.active {
    color: var(--primary);
  }

  .admin-login-card {
    @apply glass-elevated glass-shimmer p-8 md:p-10;
  }

  .admin-theme-toggle {
    @apply interactive-min p-2 rounded-lg border transition-colors duration-200;
    color: var(--text-muted);
    border-color: var(--glass-border);
    background: color-mix(in srgb, var(--glass-bg) 80%, transparent);
  }
  .admin-theme-toggle:hover {
    color: var(--primary);
    border-color: color-mix(in srgb, var(--primary) 40%, var(--glass-border));
    background: var(--green-tint);
  }
}

@layer utilities {
  .animate-fade-in {
    animation: fadeIn 0.8s ease-in-out;
  }
  .animate-slide-up {
    animation: slideUp 0.8s ease-out;
  }
  @keyframes fadeIn {
    0% { opacity: 0; transform: translateY(20px); }
    100% { opacity: 1; transform: translateY(0); }
  }
  @keyframes slideUp {
    0% { opacity: 0; transform: translateY(40px); }
    100% { opacity: 1; transform: translateY(0); }
  }
  .text-gradient {
    background: linear-gradient(135deg, var(--primary) 0%, var(--accent-warm) 50%, var(--primary) 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  ::selection {
    background: rgba(138, 111, 78, 0.28);
    color: var(--foreground);
  }
  ::-webkit-scrollbar {
    width: 6px;
  }
  ::-webkit-scrollbar-track {
    background: var(--background);
  }
  ::-webkit-scrollbar-thumb {
    background: var(--muted);
    border-radius: 4px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: var(--muted-foreground);
  }
  @keyframes blink {
    0%, 100% { opacity: 1; }
    50%       { opacity: 0; }
  }
  .terminal-cursor {
    animation: blink 1s step-end infinite;
  }
  .font-serif {
    font-family: var(--font-serif);
  }
}

