import type { Metadata } from 'next'
import { ThemeProvider } from 'next-themes'
import Script from 'next/script'
import './globals.css'

export const metadata: Metadata = {
  title: 'Kennedy Muritu — Systems Architect & Creative Technologist',
  description:
    'Kennedy Muritu is a systems architect, creative technologist, and purposeful builder based in Kenya. Building digital systems that serve people.',
  metadataBase: new URL(process.env.NEXT_PUBLIC_SITE_URL ?? 'https://kennedymuritu.vercel.app'),
  openGraph: {
    title: 'Kennedy Muritu — Systems Architect & Creative Technologist',
    description:
      'Systems architect and creative technologist based in Kenya. Portfolio, writing, and contact.',
    url: 'https://kennedymuritu.vercel.app',
    siteName: 'Kennedy Muritu',
    type: 'website',
    locale: 'en_KE',
  },
  twitter: { card: 'summary_large_image', creator: '@muri_tuu' },
  icons: { icon: '/favicon.svg' },
}

export default function RootLayout({ children }: { children: React.ReactNode }) {
  return (
    <html lang="en" suppressHydrationWarning>
      <head>
        <Script id="tawk-to" strategy="afterInteractive">
          {`var Tawk_API=Tawk_API||{}, Tawk_LoadStart=new Date();
(function(){
  var s1=document.createElement("script"),s0=document.getElementsByTagName("script")[0];
  s1.async=1;
  s1.src='https://embed.tawk.to/690143ef75c9fe1957a9a18d/1j8mf2oto';
  s1.charset='UTF-8';
  s1.setAttribute('crossorigin','*');
  s0.parentNode.insertBefore(s1,s0);
})();`}
        </Script>
      </head>
      <body className="font-sans antialiased">
        <ThemeProvider attribute="class" defaultTheme="dark" enableSystem={false}>
          {children}
        </ThemeProvider>
      </body>
    </html>
  )
}

